using NovaHarvest.Core.Player;
using NovaHarvest.Core.World;
namespace NovaHarvest.Core.Systems; public sealed class InteractionSystem { readonly PlayerController _player; readonly Inventory _inventory; public InteractionSystem(PlayerController player, Inventory inventory) { _player = player; _inventory = inventory; } public IReadOnlyList<WorldObject> GetAvailableInteractions(WorldManager world, int radius = 1) => _player.GetNearbyObjects(world, radius).Where(x => x.IsInteractable).ToList(); public bool Interact(WorldManager world, string objectId) { var o = world.Find(objectId); if (o is null || !CanInteract(o)) return false; if (o is ResourceNode r) return Gather(r); return o.Type switch { WorldObjectType.Chest => OpenChest(), WorldObjectType.Plant => CollectPlant(), WorldObjectType.Ruins => ExploreRuins(), WorldObjectType.Ship => true, WorldObjectType.Campfire => true, WorldObjectType.FarmPlot => true, _ => false }; } bool CanInteract(WorldObject o) => o.IsInteractable && Math.Abs(o.X - _player.Position.X) <= 1 && Math.Abs(o.Y - _player.Position.Y) <= 1; bool Gather(ResourceNode r) { var n = r.Gather(1); if (n <= 0) return false; _inventory.Add(r.ResourceId, n); return true; } bool OpenChest() { _inventory.Add("alien_scrap", 3); _inventory.Add("seed_lumen_berry", 2); return true; } bool CollectPlant() { _inventory.Add("alien_plant", 1); return true; } bool ExploreRuins() { _inventory.Add("ancient_artifact", 1); return true; } }
